/**
 * Merge one customer into another.
 * Removes fromId customer and reassigns all their invoices to intoId.
 * @param {Array} customers
 * @param {Array} invoices
 * @param {string} fromId
 * @param {string} intoId
 * @returns {ok({ customers, invoices }) | fail(code)}
